#!/usr/bin/env node
/**
 * One process, one nonce claim. Used by the multi-process replay test:
 * exclusion across PROCESSES cannot be tested inside a single event loop, and
 * a store that survives restarts is worthless if two instances on one host can
 * both claim the same nonce.
 *
 * Prints WON when this process took the claim, LOST when it was already held,
 * and FULL when the store refused because every slot holds a LIVE claim.
 * Any other output is a bug.
 *
 * `maxEntries` and `ttlMs` are optional, and exist so the saturation test can
 * fill the table from separate processes — capacity is a property of the
 * persisted file, so it has to be provable across processes and not just
 * within one event loop.
 */
import { NonceStoreAtCapacityError } from '../dist/nonce-store.js';
import { PersistentNonceStore } from '../dist/persistent-nonce-store.js';

const [base, nonce, maxEntries, ttlMs] = process.argv.slice(2);
const store = new PersistentNonceStore({
  base,
  ...(maxEntries ? { maxEntries: Number(maxEntries) } : {}),
  ...(ttlMs ? { ttlMs: Number(ttlMs) } : {}),
});

try {
  const token = await store.claim({
    network: 'celo-sepolia',
    asset: '0x01C5C0122039549AD1493B8220cABEdD739BC44E',
    from: '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266',
    nonce,
  });
  process.stdout.write(token === null ? 'LOST' : 'WON');
} catch (err) {
  process.stdout.write(err instanceof NonceStoreAtCapacityError ? 'FULL' : `ERR:${err.message}`);
}
